const net = require("node:net");

const socket = net.createConnection({ host: "localhost", port: 8000 }, () => {
  let httpPayload =
    "";

  let httpPayloadBuff = Buffer.from(httpPayload, "hex");
  socket.write(httpPayloadBuff);
});

socket.on("data", (data) => {
  console.log(data.toString('utf-8'));
});
